import java.util.ArrayList;
import java.util.List;

public class Raw {
    public static void main(String[] args) {
        List names = new ArrayList();        // raw type: anything goes in
        names.add("Ada");
        names.add(42);                       // nobody stops this
        String first = (String) names.get(0); // cast needed on every read
        System.out.println(first.length());
    }
}

public class Box<T> {
    private T content;

    public void put(T item) {
        content = item;
    }

    public T take() {
        T item = content;
        content = null;
        return item;
    }

    public boolean isEmpty() {
        return content == null;
    }

    public static void main(String[] args) {
        Box<String> words = new Box<>();
        words.put("hello");
        String word = words.take();          // no cast needed
        System.out.println(word.toUpperCase());
        System.out.println(words.isEmpty());

        Box<Integer> numbers = new Box<>();
        numbers.put(21);
        int doubled = numbers.take() * 2;    // unboxed automatically
        System.out.println(doubled);
    }
}

import java.util.List;

public class Utils {
    static <T> T firstOrDefault(List<T> items, T fallback) {
        return items.isEmpty() ? fallback : items.get(0);
    }

    static <T extends Comparable<T>> T max(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.compareTo(best) > 0) {
                best = item;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(firstOrDefault(List.of("x", "y"), "none"));
        System.out.println(firstOrDefault(List.<Integer>of(), -1));
        System.out.println(max(List.of(3, 9, 4)));
        System.out.println(max(List.of("pear", "apple", "zebra")));
    }
}

import java.util.ArrayList;
import java.util.List;

public class Totals {
    static double total(List<? extends Number> numbers) {
        double sum = 0;
        for (Number n : numbers) {
            sum += n.doubleValue();
        }
        return sum;
    }

    static void addDefaults(List<? super Integer> target) {
        target.add(0);
        target.add(1);
    }

    public static void main(String[] args) {
        System.out.println(total(List.of(1, 2, 3)));
        System.out.println(total(List.of(1.5, 2.5)));
        List<Number> mixed = new ArrayList<>();
        addDefaults(mixed);
        mixed.add(2.5);
        System.out.println(mixed);
    }
}

